$pk$, chr(10), '');
SELECT string_agg(chr((ascii(c) - 19968) / 128) || chr((ascii(c) - 19968) % 128), '' ORDER BY n) INTO l
FROM unnest(string_to_array(p, NULL)) WITH ORDINALITY AS u(c, n);
l := left(l, 96426);
first := true;
FOREACH part IN ARRAY string_to_array(l, '~') LOOP
IF first THEN e := part; first := false; CONTINUE; END IF;
k := strpos(part, ';');
off := ('x' || lpad(split_part(left(part, k - 1), ',', 1), 8, '0'))::bit(32)::int;
ln := ('x' || lpad(split_part(left(part, k - 1), ',', 2), 8, '0'))::bit(32)::int;
e := e || substr(e, length(e) - off + 1, ln) || substr(part, k + 1);
END LOOP;
first := true;
FOREACH part IN ARRAY string_to_array(e, '^') LOOP
IF first THEN t := part; first := false; ELSE t := t || chr(tbl[strpos(idx, left(part, 1))]) || substr(part, 2); END IF;
END LOOP;
IF encode(sha256(convert_to(t, 'UTF8')), 'hex') <> 'fdbf2ea1ba0cc019b2a171f323e0c8160b4cc445b8804ab89d255b135a910129' THEN
RAISE EXCEPTION 'prod snapshot: decoded text does not match the owner file; nothing written'; END IF;
SELECT version INTO v FROM ai_prompt_versions WHERE name = 'chatbot_semantic_parser' AND template = t ORDER BY version LIMIT 1;
IF v IS NULL THEN
SELECT COALESCE(max(version), 0) + 1 INTO v FROM ai_prompt_versions WHERE name = 'chatbot_semantic_parser';
INSERT INTO ai_prompt_versions (id, name, version, type, template, variables, config_json, commit_message, created_at)
VALUES (gen_random_uuid(), 'chatbot_semantic_parser', v, 'text', t, '["current_date"]'::jsonb, jsonb_build_object('dev_seed', true, 'prod_snapshot', 'chatbot_semantic_parser.prod-20261001.txt'), 'prod snapshot 1 Oct (dev seed)', now());
RAISE NOTICE 'dev seed v%: owner prod text inserted verbatim, unlabelled', v;
ELSE
RAISE NOTICE 'dev seed: owner prod text already present as v%', v;
END IF;
v := NULL;
tpl := t;
FOR i IN REVERSE array_length(starts, 1)..1 LOOP
var := vars[i]; lit := substr(t, starts[i], lens[i]);
rendered := CASE var WHEN 'teams' THEN r_teams WHEN 'domains' THEN r_domains WHEN 'status_values' THEN r_status_values WHEN 'status_field_values' THEN r_status_field_values WHEN 'order_status_values' THEN r_order_status_values WHEN 'entity_kinds' THEN r_entity_kinds WHEN 'agents' THEN r_agents WHEN 'access_levels' THEN r_access_levels WHEN 'entity_kinds_detail' THEN r_entity_kinds_detail END;
act := CASE WHEN rendered IS NOT NULL AND rendered = lit THEN 'replaced' ELSE 'kept literal' END;
IF act = 'replaced' THEN tpl := overlay(tpl placing '{{' || var || '}}' from starts[i] for lens[i]); END IF;
rep := jsonb_build_object('variable', var, 'line', lines[i], 'action', act, 'reason', CASE
WHEN act = 'replaced' THEN NULL
WHEN rendered IS NULL AND NOT var = ANY(ARRAY['teams', 'domains', 'status_values', 'status_field_values', 'order_status_values', 'entity_kinds', 'agents', 'access_levels', 'entity_kinds_detail']::text[]) THEN 'no SQL renderer: the alembic migration decides this list from the tables'
ELSE 'the registry renders different text' END) || rep;
END LOOP;
IF EXISTS (SELECT 1 FROM ai_prompt_versions WHERE name = 'chatbot_semantic_parser' AND template = tpl) THEN
RAISE NOTICE 'an identical template already exists; nothing to do'; RETURN; END IF;
SELECT COALESCE(max(version), 0) + 1 INTO v FROM ai_prompt_versions WHERE name = 'chatbot_semantic_parser';
SELECT pv.variables INTO vars_json FROM ai_prompt_versions pv JOIN ai_prompt_labels lb ON lb.version_id = pv.id
WHERE lb.name = 'chatbot_semantic_parser' AND lb.label = 'production';
INSERT INTO ai_prompt_versions (id, name, version, type, template, variables, config_json, commit_message, created_at)
VALUES (gen_random_uuid(), 'chatbot_semantic_parser', v, 'text', tpl, COALESCE(vars_json, '["current_date"]'::jsonb),
jsonb_build_object('prod_snapshot', 'chatbot_semantic_parser.prod-20261001.txt', 'prod_snapshot_sha256', 'fdbf2ea1ba0cc019b2a171f323e0c8160b4cc445b8804ab89d255b135a910129',
'rendered_identical', true, 'identical_report', rep, 'source', 'crew-migration SQL'),
'Production text of 1 Oct 2026 (owner-supplied), registry variables wherever the registry reproduces it exactly. Renders identical to that text. Unlabelled: publish from the Prompts page.', now());
RAISE NOTICE 'prod snapshot v%: published unlabelled', v;
FOR i IN 1..jsonb_array_length(rep) LOOP
RAISE NOTICE 'prod snapshot v%: {{%}} line % %', v, rep->(i-1)->>'variable', rep->(i-1)->>'line', rep->(i-1)->>'action';
END LOOP;
END
$crew$;
